UPDATE wf_form
set form_code = #{formCode},form_name = #{formName},
form_url = #{formUrl},update_by = #{updateBy},update_date = #{updateDate},
remarks = #{remarks}
WHERE id = #{id}

mapper.select:
SELECT

FROM wf_form a



        AND a.form_code like #{formCode}



        AND a.form_name like #{formName}


        AND a.tenant_Id = #{tenantId}
